    "css": "#mff-home .t-Region-body{padding:0!important;background:transparent!important;}\n.finova-dashboard-region{border:0!important;box-shadow:none!important;background:transparent!important;}\n.fin-dashboard{width:100%!important;display:flex;flex-direction:column;gap:16px;}\n.fin-d-topbar{display:flex;align-items:flex-start;justify-content:space-between;gap:18px;flex-wrap:wrap;}\n.fin-d-title h1{margin:0;font-size:22px;line-height:1.15;color:#0d2f4c;font-weight:800;}\n.fin-d-title p{margin:6px 0 0;color:#668090;font-size:14px;}\n.fin-d-right{display:flex;align-items:center;gap:18px;flex-wrap:wrap;margin-left:auto;}\n.fin-d-date{display:flex;align-items:center;gap:8px;color:#556f80;font-size:14px;font-weight:600;}\n.fin-d-newbtn{display:inline-flex;align-items:center;gap:10px;background:#f7901e;color:#fff!important;text-decoration:none;border-radius:12px;padding:14px 20px;font-weight:800;box-shadow:0 10px 22px rgba(247,144,30,.24);}\n.fin-kpi-grid{display:grid!important;grid-template-columns:repeat(6,minmax(0,1fr))!important;gap:12px!important;}\n.fin-kpi{background:#fff;border:1px solid #dce7eb;border-radius:14px;padding:14px 16px;box-shadow:0 3px 12px rgba(9,52,61,.05);display:flex;flex-direction:column;gap:8px;min-height:118px;}\n.fin-kpi-head{display:flex;align-items:center;gap:12px;}\n.fin-kpi-icon{width:42px;height:42px;border-radius:10px;background:#eef5f5;color:#0c6a74;display:flex;align-items:center;justify-content:center;font-size:22px;flex:0 0 42px;}\n.fin-kpi.alert .fin-kpi-icon{background:#fff0ef;color:#e53935;}\n.fin-kpi.focus{background:#fff9f2;border-color:#f0c58d;}\n.fin-kpi-value{font-size:22px;font-weight:800;line-height:1.1;color:#0d2f4c;}\n.fin-kpi-label{font-size:13px;font-weight:700;color:#17324a;}\n.fin-kpi-delta{display:flex;align-items:center;gap:8px;font-size:11px;font-weight:700;color:#6c8693;margin-top:auto;}\n.fin-grid-2{display:grid!important;grid-template-columns:1.15fr 1fr!important;gap:14px!important;}\n.fin-card{background:#fff;border:1px solid #dbe7eb;border-radius:14px;box-shadow:0 3px 12px rgba(8,54,64,.05);overflow:hidden;}\n.fin-card-header{display:flex;align-items:center;justify-content:space-between;gap:10px;padding:14px 16px;border-bottom:1px solid #ebf1f3;color:#0d2f4c;font-weight:800;font-size:16px;}\n.fin-card-link{color:#1a71cf!important;text-decoration:none;font-weight:700;font-size:13px;}\n.fin-card-body{padding:16px;}\n.fin-pipeline{display:grid;grid-template-columns:repeat(5,minmax(0,1fr));align-items:flex-start;gap:10px;position:relative;}\n.fin-stage{text-align:center;position:relative;}\n.fin-stage-badge{width:56px;height:56px;border-radius:50%;margin:0 auto 10px;background:linear-gradient(180deg,#15956c 0%,#097754 100%);color:#fff;display:flex;align-items:center;justify-content:center;font-size:22px;font-weight:800;box-shadow:0 6px 14px rgba(11,119,90,.18);}\n.fin-stage.gray .fin-stage-badge{background:#95a4a7;box-shadow:none;}\n.fin-stage.orange .fin-stage-badge{background:linear-gradient(180deg,#ffa82e 0%,#f48a15 100%);}\n.fin-stage-label{color:#17324a;font-size:13px;font-weight:800;line-height:1.35;min-height:34px;}\n.fin-stage-pct{margin-top:4px;color:#587180;font-size:12px;font-weight:700;}\n.mff-ar{display:none}.mff-rtl .mff-en{display:none}.mff-rtl .mff-ar{display:inline}\n@media(max-width:1100px){.fin-kpi-grid{grid-template-columns:repeat(3,1fr)!important}.fin-grid-2{grid-template-columns:1fr!important}}\n@media(max-width:650px){.fin-kpi-grid{grid-template-columns:1fr!important}.fin-pipeline{grid-template-columns:1fr 1fr!important}}",
